-- Studio PR B private artifact authority.
-- Exact current approved PR A versions only; legacy document_generations is excluded.
INSERT INTO public.capabilities(capability_key,module,description) VALUES
 ('studio.artifacts.rendition.generate','docs','Generate private Studio renditions'),
 ('studio.artifacts.download','docs','Download private Studio renditions'),
 ('studio.artifacts.retention.manage','docs','Manage Studio rendition retention'),
 ('studio.artifacts.legal_hold.manage','docs','Manage Studio rendition legal holds'),
 ('studio.artifacts.delete.request','docs','Request Studio rendition deletion'),
 ('studio.artifacts.delete.approve','docs','Independently resolve Studio rendition deletion')
ON CONFLICT(capability_key) DO UPDATE SET module=excluded.module,description=excluded.description;
CREATE TABLE public.studio_private_artifact_runtime_control(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),enabled boolean NOT NULL DEFAULT true,read_only boolean NOT NULL DEFAULT false,provider_enabled boolean NOT NULL DEFAULT true,download_enabled boolean NOT NULL DEFAULT true,deletion_enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.studio_private_artifact_runtime_control(singleton) VALUES(true);
CREATE TABLE public.studio_retention_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid,workspace_id uuid,artifact_type text CHECK(artifact_type IN('brd','frd','pdd')),policy_version bigint NOT NULL CHECK(policy_version>0),retention_days integer CHECK(retention_days IS NULL OR retention_days>=0),indefinite boolean NOT NULL,effective_at timestamptz NOT NULL,published_by uuid REFERENCES public.profiles(id),publisher_authorization_version bigint,receipt_id uuid UNIQUE,audit_event_id uuid UNIQUE,system_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK((indefinite AND retention_days IS NULL) OR (NOT indefinite AND retention_days IS NOT NULL)),CHECK((system_default AND org_id IS NULL AND workspace_id IS NULL AND artifact_type IS NULL AND published_by IS NULL AND receipt_id IS NULL) OR (NOT system_default AND org_id IS NOT NULL AND workspace_id IS NOT NULL AND artifact_type IS NOT NULL AND published_by IS NOT NULL AND publisher_authorization_version IS NOT NULL AND receipt_id IS NOT NULL)),UNIQUE(org_id,workspace_id,artifact_type,policy_version));
CREATE UNIQUE INDEX studio_one_system_default_retention_policy ON public.studio_retention_policies(system_default) WHERE system_default;
INSERT INTO public.studio_retention_policies(id,policy_version,indefinite,effective_at,system_default) VALUES('00000000-0000-4000-8000-000000000001',1,true,'-infinity',true);
CREATE TABLE public.studio_private_artifact_command_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,workspace_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id),command_type text NOT NULL CHECK(command_type IN('studio.rendition.generate','studio.retention.policy.publish','studio.rendition.retention.extend','studio.legal_hold.place','studio.legal_hold.release','studio.rendition.deletion.request','studio.rendition.deletion.resolve')),idempotency_key text NOT NULL CHECK(length(btrim(idempotency_key)) BETWEEN 1 AND 200),request_id uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash~'^[0-9a-f]{64}$'),status text NOT NULL CHECK(status='committed'),resource_id uuid NOT NULL,response jsonb NOT NULL CHECK(jsonb_typeof(response)='object'),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,actor_id,command_type,idempotency_key),FOREIGN KEY(workspace_id,org_id) REFERENCES public.workspaces(id,org_id) ON DELETE RESTRICT);
CREATE TABLE public.studio_rendition_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rendition_id uuid NOT NULL DEFAULT gen_random_uuid(),opaque_object_id uuid NOT NULL DEFAULT gen_random_uuid(),org_id uuid NOT NULL,workspace_id uuid NOT NULL,artifact_id uuid NOT NULL,artifact_version_id uuid NOT NULL,artifact_version bigint NOT NULL CHECK(artifact_version>0),artifact_type text NOT NULL CHECK(artifact_type IN('brd','frd','pdd')),format text NOT NULL CHECK(format IN('markdown','pdf','docx')),renderer_version text NOT NULL,template_version text NOT NULL,content_schema_version text NOT NULL,requested_by uuid NOT NULL REFERENCES public.profiles(id),requester_authorization_version bigint NOT NULL CHECK(requester_authorization_version>0),request_id uuid NOT NULL,receipt_id uuid NOT NULL UNIQUE REFERENCES public.studio_private_artifact_command_receipts(id),reconciliation_count integer NOT NULL DEFAULT 0 CHECK(reconciliation_count BETWEEN 0 AND 3),reconciliation_claimed_at timestamptz,state text NOT NULL CHECK(state IN('requested','rendering','uploaded','available','failed','reconciliation_required','reconciling')),storage_provider text CHECK(storage_provider IS NULL OR storage_provider='supabase'),bucket_id text CHECK(bucket_id IS NULL OR bucket_id='studio-private-artifacts'),object_key text,content_hash text CHECK(content_hash IS NULL OR content_hash~'^[0-9a-f]{64}$'),byte_length bigint CHECK(byte_length IS NULL OR byte_length>0),mime_type text,safe_filename text,failure_code text CHECK(failure_code IS NULL OR failure_code~'^[A-Z0-9_]{1,64}$'),created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,rendered_at timestamptz,completed_at timestamptz,UNIQUE(id,org_id,workspace_id),UNIQUE(rendition_id),UNIQUE(opaque_object_id),FOREIGN KEY(artifact_id,org_id,workspace_id) REFERENCES public.studio_artifact_aggregates(id,org_id,workspace_id) ON DELETE RESTRICT,FOREIGN KEY(artifact_version_id,artifact_id,org_id,workspace_id) REFERENCES public.studio_artifact_versions(id,artifact_id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX studio_one_active_rendition_attempt ON public.studio_rendition_attempts(artifact_version_id,format,renderer_version) WHERE state IN('requested','rendering','uploaded','reconciliation_required','reconciling');
CREATE TABLE public.studio_renditions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL UNIQUE,org_id uuid NOT NULL,workspace_id uuid NOT NULL,artifact_id uuid NOT NULL,artifact_version_id uuid NOT NULL,artifact_version bigint NOT NULL CHECK(artifact_version>0),artifact_type text NOT NULL CHECK(artifact_type IN('brd','frd','pdd')),format text NOT NULL CHECK(format IN('markdown','pdf','docx')),mime_type text NOT NULL,safe_filename text NOT NULL CHECK(safe_filename~'^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$'),storage_provider text NOT NULL CHECK(storage_provider='supabase'),bucket_id text NOT NULL CHECK(bucket_id='studio-private-artifacts'),object_key text NOT NULL,byte_length bigint NOT NULL CHECK(byte_length>0),content_hash text NOT NULL CHECK(content_hash~'^[0-9a-f]{64}$'),renderer_version text NOT NULL,template_version text NOT NULL,content_schema_version text NOT NULL,retention_policy_id uuid NOT NULL REFERENCES public.studio_retention_policies(id),retention_policy_version bigint NOT NULL CHECK(retention_policy_version>0),retention_indefinite boolean NOT NULL,retention_until timestamptz,lifecycle text NOT NULL CHECK(lifecycle IN('available','deletion_requested','deleting','deleted','deletion_failed')),lifecycle_version bigint NOT NULL DEFAULT 1 CHECK(lifecycle_version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(id,org_id,workspace_id),UNIQUE(artifact_version_id,format,renderer_version),CHECK((retention_indefinite AND retention_until IS NULL) OR (NOT retention_indefinite AND retention_until IS NOT NULL)),CHECK((lifecycle='deleted' AND deleted_at IS NOT NULL) OR (lifecycle<>'deleted' AND deleted_at IS NULL)),FOREIGN KEY(attempt_id,org_id,workspace_id) REFERENCES public.studio_rendition_attempts(id,org_id,workspace_id) ON DELETE RESTRICT,FOREIGN KEY(artifact_id,org_id,workspace_id) REFERENCES public.studio_artifact_aggregates(id,org_id,workspace_id) ON DELETE RESTRICT,FOREIGN KEY(artifact_version_id,artifact_id,org_id,workspace_id) REFERENCES public.studio_artifact_versions(id,artifact_id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE TABLE public.studio_rendition_retention_extensions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rendition_id uuid NOT NULL,org_id uuid NOT NULL,workspace_id uuid NOT NULL,extended_until timestamptz,indefinite boolean NOT NULL,rationale text NOT NULL CHECK(length(btrim(rationale)) BETWEEN 1 AND 4000),actor_id uuid NOT NULL REFERENCES public.profiles(id),actor_authorization_version bigint NOT NULL,receipt_id uuid NOT NULL UNIQUE REFERENCES public.studio_private_artifact_command_receipts(id),audit_event_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),CHECK((indefinite AND extended_until IS NULL) OR (NOT indefinite AND extended_until IS NOT NULL)),FOREIGN KEY(rendition_id,org_id,workspace_id) REFERENCES public.studio_renditions(id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE TABLE public.studio_rendition_legal_hold_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hold_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('placed','released')),place_event_id uuid,rendition_id uuid NOT NULL,org_id uuid NOT NULL,workspace_id uuid NOT NULL,rationale text NOT NULL CHECK(length(btrim(rationale)) BETWEEN 1 AND 4000),actor_id uuid NOT NULL REFERENCES public.profiles(id),actor_authorization_version bigint NOT NULL,receipt_id uuid NOT NULL UNIQUE REFERENCES public.studio_private_artifact_command_receipts(id),audit_event_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(hold_id,event_type),CHECK((event_type='placed' AND place_event_id IS NULL AND id=hold_id) OR (event_type='released' AND place_event_id IS NOT NULL)),FOREIGN KEY(place_event_id) REFERENCES public.studio_rendition_legal_hold_events(id) ON DELETE RESTRICT,FOREIGN KEY(rendition_id,org_id,workspace_id) REFERENCES public.studio_renditions(id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE TABLE public.studio_rendition_deletion_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rendition_id uuid NOT NULL,org_id uuid NOT NULL,workspace_id uuid NOT NULL,requested_by uuid NOT NULL REFERENCES public.profiles(id),requester_authorization_version bigint NOT NULL,rationale text NOT NULL CHECK(length(btrim(rationale)) BETWEEN 1 AND 4000),requested_lifecycle text NOT NULL,requested_lifecycle_version bigint NOT NULL,retention_evaluation jsonb NOT NULL CHECK(jsonb_typeof(retention_evaluation)='object'),active_hold_count integer NOT NULL CHECK(active_hold_count>=0),receipt_id uuid NOT NULL UNIQUE REFERENCES public.studio_private_artifact_command_receipts(id),audit_event_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,rendition_id,org_id,workspace_id),FOREIGN KEY(rendition_id,org_id,workspace_id) REFERENCES public.studio_renditions(id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX studio_one_unresolved_deletion_request ON public.studio_rendition_deletion_requests(rendition_id);
CREATE TABLE public.studio_rendition_deletion_resolutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL UNIQUE,rendition_id uuid NOT NULL,org_id uuid NOT NULL,workspace_id uuid NOT NULL,resolved_by uuid NOT NULL REFERENCES public.profiles(id),resolver_authorization_version bigint NOT NULL,outcome text NOT NULL CHECK(outcome IN('approved','rejected')),rationale text NOT NULL CHECK(length(btrim(rationale)) BETWEEN 1 AND 4000),retention_evaluation jsonb NOT NULL CHECK(jsonb_typeof(retention_evaluation)='object'),active_hold_count integer NOT NULL CHECK(active_hold_count>=0),receipt_id uuid NOT NULL UNIQUE REFERENCES public.studio_private_artifact_command_receipts(id),audit_event_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,rendition_id,org_id,workspace_id),FOREIGN KEY(request_id,rendition_id,org_id,workspace_id) REFERENCES public.studio_rendition_deletion_requests(id,rendition_id,org_id,workspace_id) ON DELETE RESTRICT,FOREIGN KEY(rendition_id,org_id,workspace_id) REFERENCES public.studio_renditions(id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE TABLE public.studio_rendition_deletion_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),resolution_id uuid NOT NULL UNIQUE,request_id uuid NOT NULL,rendition_id uuid NOT NULL,org_id uuid NOT NULL,workspace_id uuid NOT NULL,reconciliation_count integer NOT NULL DEFAULT 0 CHECK(reconciliation_count BETWEEN 0 AND 3),reconciliation_claimed_at timestamptz,state text NOT NULL CHECK(state IN('requested','completed','failed','reconciliation_required','reconciling')),failure_code text CHECK(failure_code IS NULL OR failure_code~'^[A-Z0-9_]{1,64}$'),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(id,rendition_id,org_id,workspace_id),FOREIGN KEY(resolution_id,rendition_id,org_id,workspace_id) REFERENCES public.studio_rendition_deletion_resolutions(id,rendition_id,org_id,workspace_id) ON DELETE RESTRICT,FOREIGN KEY(request_id,rendition_id,org_id,workspace_id) REFERENCES public.studio_rendition_deletion_requests(id,rendition_id,org_id,workspace_id) ON DELETE RESTRICT,FOREIGN KEY(rendition_id,org_id,workspace_id) REFERENCES public.studio_renditions(id,org_id,workspace_id) ON DELETE RESTRICT);
CREATE TABLE public.studio_artifact_download_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,workspace_id uuid NOT NULL,rendition_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id),actor_authorization_version bigint NOT NULL,request_id uuid NOT NULL,idempotency_key text NOT NULL CHECK(length(btrim(idempotency_key)) BETWEEN 1 AND 200),request_hash text NOT NULL CHECK(request_hash~'^[0-9a-f]{64}$'),status text NOT NULL CHECK(status IN('claimed','completed','failed')),failure_code text CHECK(failure_code IS NULL OR failure_code~'^[A-Z0-9_]{1,64}$'),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(org_id,actor_id,idempotency_key),UNIQUE(id,rendition_id,org_id,workspace_id),FOREIGN KEY(rendition_id,org_id,workspace_id) REFERENCES public.studio_renditions(id,org_id,workspace_id) ON DELETE RESTRICT);
DROP INDEX studio_one_unresolved_deletion_request;
CREATE OR REPLACE FUNCTION public.studio_private_reject_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION USING MESSAGE='STUDIO_PRIVATE_IMMUTABLE';END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_attempt_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['state','storage_provider','bucket_id','object_key','content_hash','byte_length','mime_type','safe_filename','failure_code','reconciliation_count','reconciliation_claimed_at','started_at','rendered_at','completed_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','storage_provider','bucket_id','object_key','content_hash','byte_length','mime_type','safe_filename','failure_code','reconciliation_count','reconciliation_claimed_at','started_at','rendered_at','completed_at']) THEN RAISE EXCEPTION USING MESSAGE='STUDIO_PRIVATE_IMMUTABLE';END IF;RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['lifecycle','lifecycle_version','updated_at','deleted_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['lifecycle','lifecycle_version','updated_at','deleted_at']) THEN RAISE EXCEPTION USING MESSAGE='STUDIO_PRIVATE_IMMUTABLE';END IF;RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION public.studio_private_status_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['state','status','failure_code','completed_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','status','failure_code','completed_at']) THEN RAISE EXCEPTION USING MESSAGE='STUDIO_PRIVATE_IMMUTABLE';END IF;RETURN NEW;END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['studio_retention_policies','studio_private_artifact_command_receipts','studio_rendition_retention_extensions','studio_rendition_legal_hold_events','studio_rendition_deletion_requests','studio_rendition_deletion_resolutions'] LOOP EXECUTE format('CREATE TRIGGER trg_%I_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.studio_private_reject_immutable()',t,t);END LOOP;END$$;
CREATE TRIGGER trg_studio_rendition_attempt_guard BEFORE UPDATE OR DELETE ON public.studio_rendition_attempts FOR EACH ROW EXECUTE FUNCTION public.studio_rendition_attempt_guard();
CREATE TRIGGER trg_studio_rendition_guard BEFORE UPDATE OR DELETE ON public.studio_renditions FOR EACH ROW EXECUTE FUNCTION public.studio_rendition_guard();
CREATE TRIGGER trg_studio_deletion_attempt_status_guard BEFORE UPDATE OR DELETE ON public.studio_rendition_deletion_attempts FOR EACH ROW EXECUTE FUNCTION public.studio_private_status_guard();
CREATE TRIGGER trg_studio_download_receipt_status_guard BEFORE UPDATE OR DELETE ON public.studio_artifact_download_receipts FOR EACH ROW EXECUTE FUNCTION public.studio_private_status_guard();
CREATE OR REPLACE FUNCTION public.studio_effective_retention(p_rendition uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT jsonb_build_object('indefinite',r.retention_indefinite OR COALESCE(x.indefinite,false),'retentionUntil',CASE WHEN r.retention_indefinite OR COALESCE(x.indefinite,false) THEN NULL ELSE GREATEST(r.retention_until,x.extended_until) END,'policyVersion',r.retention_policy_version) FROM public.studio_renditions r LEFT JOIN LATERAL(SELECT bool_or(e.indefinite) indefinite,max(e.extended_until) extended_until FROM public.studio_rendition_retention_extensions e WHERE e.rendition_id=r.id)x ON true WHERE r.id=p_rendition$$;
CREATE OR REPLACE FUNCTION public.studio_active_hold_count(p_rendition uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT count(*)::integer FROM public.studio_rendition_legal_hold_events p WHERE p.rendition_id=p_rendition AND p.event_type='placed' AND NOT EXISTS(SELECT 1 FROM public.studio_rendition_legal_hold_events r WHERE r.hold_id=p.hold_id AND r.event_type='released')$$;
CREATE OR REPLACE FUNCTION public.studio_private_projection_unchecked(p_org uuid,p_workspace uuid,p_artifact_version uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT jsonb_build_object('artifactVersionId',v.id,'artifactId',v.artifact_id,'artifactVersion',v.version,'artifactType',a.artifact_type,'approved',v.lifecycle='approved','readOnly',NOT ctl.enabled OR ctl.read_only,'renditions',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',r.id,'format',r.format,'mimeType',r.mime_type,'safeFilename',r.safe_filename,'byteLength',r.byte_length,'contentHash',r.content_hash,'rendererVersion',r.renderer_version,'lifecycle',r.lifecycle,'lifecycleVersion',r.lifecycle_version,'retention',public.studio_effective_retention(r.id),'legalHoldActive',public.studio_active_hold_count(r.id)>0,'deletion',CASE WHEN dr.id IS NULL THEN NULL ELSE jsonb_build_object('requestId',dr.id,'status',COALESCE(ds.outcome,'pending'),'attemptState',da.state) END,'createdAt',r.created_at,'deletedAt',r.deleted_at) ORDER BY r.format,r.created_at,r.id) FROM public.studio_renditions r LEFT JOIN LATERAL(SELECT d.* FROM public.studio_rendition_deletion_requests d WHERE d.rendition_id=r.id ORDER BY d.created_at DESC,d.id DESC LIMIT 1)dr ON true LEFT JOIN public.studio_rendition_deletion_resolutions ds ON ds.request_id=dr.id LEFT JOIN public.studio_rendition_deletion_attempts da ON da.resolution_id=ds.id WHERE r.artifact_version_id=v.id AND r.org_id=v.org_id AND r.workspace_id=v.workspace_id),'[]'::jsonb),'attempts',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x.id,'format',x.format,'state',x.state,'rendererVersion',x.renderer_version,'failureCode',x.failure_code,'createdAt',x.created_at) ORDER BY x.created_at,x.id) FROM public.studio_rendition_attempts x WHERE x.artifact_version_id=v.id AND x.org_id=v.org_id AND x.workspace_id=v.workspace_id),'[]'::jsonb)) FROM public.studio_artifact_versions v JOIN public.studio_artifact_aggregates a ON a.id=v.artifact_id AND a.org_id=v.org_id AND a.workspace_id=v.workspace_id CROSS JOIN public.studio_private_artifact_runtime_control ctl WHERE ctl.singleton AND v.id=p_artifact_version AND v.org_id=p_org AND v.workspace_id=p_workspace$$;
CREATE OR REPLACE FUNCTION public.studio_private_artifact_projection(p_org uuid,p_workspace uuid,p_artifact_version uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT CASE WHEN public.has_workspace_capability(p_workspace,p_org,'studio.artifacts.read') THEN public.studio_private_projection_unchecked(p_org,p_workspace,p_artifact_version) ELSE NULL END$$;
CREATE OR REPLACE FUNCTION public.studio_private_artifact_authority(p_actor uuid,p_org uuid,p_workspace uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT jsonb_build_object('actorId',p_actor,'organizationId',p_org,'workspaceId',p_workspace,'authorizationVersion',av.version,'capabilities',COALESCE((SELECT jsonb_agg(c.capability_key ORDER BY c.capability_key) FROM public.capabilities c WHERE c.capability_key=ANY(ARRAY['studio.artifacts.rendition.generate','studio.artifacts.download','studio.artifacts.retention.manage','studio.artifacts.legal_hold.manage','studio.artifacts.delete.request','studio.artifacts.delete.approve']) AND public.pr1e_actor_has_workspace_capability(p_actor,p_org,p_workspace,c.capability_key)),'[]'::jsonb)) FROM public.authorization_versions av WHERE av.org_id=p_org AND av.user_id=p_actor AND public.pr1e_actor_has_workspace_capability(p_actor,p_org,p_workspace,'studio.artifacts.read')$$;
CREATE OR REPLACE FUNCTION public.studio_private_claim_receipt(p_command text,p_actor uuid,p_org uuid,p_workspace uuid,p_request uuid,p_key text,p_hash text) RETURNS public.studio_private_artifact_command_receipts LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r public.studio_private_artifact_command_receipts;BEGIN IF p_request IS NULL OR p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;SELECT * INTO r FROM public.studio_private_artifact_command_receipts WHERE org_id=p_org AND actor_id=p_actor AND command_type=p_command AND idempotency_key=p_key FOR UPDATE;IF r.id IS NOT NULL AND (r.workspace_id<>p_workspace OR r.request_hash<>p_hash) THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;RETURN r;END$$;
DROP TRIGGER trg_studio_private_artifact_command_receipts_immutable ON public.studio_private_artifact_command_receipts;
CREATE OR REPLACE FUNCTION public.studio_private_receipt_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF TG_OP='DELETE' OR OLD.response<>'{}'::jsonb OR (to_jsonb(NEW)-ARRAY['resource_id','response']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['resource_id','response']) THEN RAISE EXCEPTION USING MESSAGE='STUDIO_PRIVATE_IMMUTABLE';END IF;RETURN NEW;END$$;
CREATE TRIGGER trg_studio_private_receipt_guard BEFORE UPDATE OR DELETE ON public.studio_private_artifact_command_receipts FOR EACH ROW EXECUTE FUNCTION public.studio_private_receipt_guard();
CREATE OR REPLACE FUNCTION public.studio_private_artifact_command_claim(p_command jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE command_type text:=p_command->>'commandType';actor uuid;org uuid;workspace uuid;request_id uuid;authorization_version bigint;key text;hash text;capability text;receipt public.studio_private_artifact_command_receipts;v public.studio_artifact_versions;kind text;x public.studio_rendition_attempts;r public.studio_renditions;p public.studio_retention_policies;dr public.studio_rendition_deletion_requests;ds public.studio_rendition_deletion_resolutions;da public.studio_rendition_deletion_attempts;hold record;control public.studio_private_artifact_runtime_control;audit_id uuid:=gen_random_uuid();result_resource_id uuid:=gen_random_uuid();result_response jsonb:='{}';claim jsonb;format_name text;renderer text;next_policy_version bigint;days integer;indef boolean;effective timestamptz;retention jsonb;holds integer;until_at timestamptz;outcome text;event_id uuid;
BEGIN
 IF p_command IS NULL OR jsonb_typeof(p_command)<>'object' OR NOT(p_command?&ARRAY['commandType','actorId','organizationId','workspaceId','requestId','idempotencyKey','authorizationVersion','payload']) OR jsonb_typeof(p_command->'payload')<>'object' THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;
 BEGIN actor:=(p_command->>'actorId')::uuid;org:=(p_command->>'organizationId')::uuid;workspace:=(p_command->>'workspaceId')::uuid;request_id:=(p_command->>'requestId')::uuid;authorization_version:=(p_command->>'authorizationVersion')::bigint;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;key:=p_command->>'idempotencyKey';
 capability:=CASE command_type WHEN 'studio.rendition.generate' THEN 'studio.artifacts.rendition.generate' WHEN 'studio.retention.policy.publish' THEN 'studio.artifacts.retention.manage' WHEN 'studio.rendition.retention.extend' THEN 'studio.artifacts.retention.manage' WHEN 'studio.legal_hold.place' THEN 'studio.artifacts.legal_hold.manage' WHEN 'studio.legal_hold.release' THEN 'studio.artifacts.legal_hold.manage' WHEN 'studio.rendition.deletion.request' THEN 'studio.artifacts.delete.request' WHEN 'studio.rendition.deletion.resolve' THEN 'studio.artifacts.delete.approve' END;
 IF capability IS NULL THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;
 -- Fresh authorization deliberately precedes receipt and resource inspection.
 PERFORM public.studio_assert_actor(actor,org,workspace,capability,authorization_version);
 hash:=encode(public.digest(convert_to(p_command::text,'UTF8'),'sha256'),'hex');receipt:=public.studio_private_claim_receipt(command_type,actor,org,workspace,request_id,key,hash);
 IF receipt.id IS NOT NULL THEN RETURN jsonb_build_object('outcome','replayed','receiptId',receipt.id,'resourceId',receipt.resource_id,'resource',receipt.response);END IF;
 SELECT * INTO control FROM public.studio_private_artifact_runtime_control WHERE singleton FOR SHARE;IF NOT control.enabled THEN RAISE EXCEPTION USING MESSAGE='STUDIO_FEATURE_DISABLED';END IF;IF control.read_only THEN RAISE EXCEPTION USING MESSAGE='STUDIO_READ_ONLY';END IF;
 INSERT INTO public.studio_private_artifact_command_receipts(org_id,workspace_id,actor_id,command_type,idempotency_key,request_id,request_hash,status,resource_id,response) VALUES(org,workspace,actor,command_type,key,request_id,hash,'committed',result_resource_id,'{}') RETURNING * INTO receipt;
 IF command_type='studio.rendition.generate' THEN
  IF NOT control.provider_enabled OR p_command->'payload'?|ARRAY['bucket','bucketId','objectKey','contentHash','byteLength','mimeType','safeFilename','rendererVersion','storageProvider'] THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;
  BEGIN format_name:=p_command#>>'{payload,format}';result_resource_id:=(p_command#>>'{payload,artifactVersionId}')::uuid;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;IF format_name NOT IN('markdown','pdf','docx') THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;
  renderer:=CASE format_name WHEN 'markdown' THEN 'studio-markdown-1' WHEN 'pdf' THEN 'studio-pdf-1' ELSE 'studio-docx-1' END;
  SELECT sv.* INTO v FROM public.studio_artifact_versions sv JOIN public.studio_artifact_aggregates a ON a.id=sv.artifact_id AND a.org_id=sv.org_id AND a.workspace_id=sv.workspace_id WHERE sv.id=result_resource_id AND sv.org_id=org AND sv.workspace_id=workspace AND a.current_approved_version_id=sv.id AND a.lifecycle='approved' AND sv.lifecycle='approved' FOR SHARE OF sv,a;SELECT a.artifact_type INTO kind FROM public.studio_artifact_aggregates a WHERE a.id=v.artifact_id AND a.org_id=org AND a.workspace_id=workspace;
  IF v.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;
  INSERT INTO public.studio_rendition_attempts(org_id,workspace_id,artifact_id,artifact_version_id,artifact_version,artifact_type,format,renderer_version,template_version,content_schema_version,requested_by,requester_authorization_version,request_id,receipt_id,state) SELECT org,workspace,v.artifact_id,v.id,v.version,kind,format_name,renderer,t.template_version,v.content_schema_version,actor,authorization_version,request_id,receipt.id,'requested' FROM public.studio_system_template_versions t WHERE t.id=v.template_id RETURNING * INTO x;
  result_resource_id:=x.id;result_response:=jsonb_build_object('attemptId',x.id,'renditionId',x.rendition_id,'artifactVersionId',x.artifact_version_id,'format',x.format,'state',x.state,'rendererVersion',x.renderer_version,'templateVersion',x.template_version,'contentSchemaVersion',x.content_schema_version);claim:=jsonb_build_object('disposition','execute','requestId',request_id,'attemptId',x.id,'renditionId',x.rendition_id,'organizationId',x.org_id,'workspaceId',x.workspace_id,'opaqueObjectId',x.opaque_object_id,'artifactId',x.artifact_id,'artifactVersionId',x.artifact_version_id,'artifactType',x.artifact_type,'format',x.format,'approvedContent',v.content,'contentSchemaVersion',x.content_schema_version,'rendererVersion',x.renderer_version,'templateVersion',x.template_version,'reconciliationCount',x.reconciliation_count);
 ELSIF command_type='studio.retention.policy.publish' THEN
  kind:=p_command#>>'{payload,artifactType}';BEGIN indef:=COALESCE((p_command#>>'{payload,indefinite}')::boolean,false);days:=NULLIF(p_command#>>'{payload,retentionDays}','')::integer;effective:=COALESCE(NULLIF(p_command#>>'{payload,effectiveAt}','')::timestamptz,now());EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;
  IF kind NOT IN('brd','frd','pdd') OR (indef AND days IS NOT NULL) OR (NOT indef AND (days IS NULL OR days<0)) THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws('|','studio-retention',org,workspace,kind),0));SELECT COALESCE(max(rp.policy_version),0)+1 INTO next_policy_version FROM public.studio_retention_policies rp WHERE rp.org_id=org AND rp.workspace_id=workspace AND rp.artifact_type=kind;
  INSERT INTO public.studio_retention_policies(org_id,workspace_id,artifact_type,policy_version,retention_days,indefinite,effective_at,published_by,publisher_authorization_version,receipt_id,audit_event_id) VALUES(org,workspace,kind,next_policy_version,days,indef,effective,actor,authorization_version,receipt.id,audit_id) RETURNING * INTO p;result_resource_id:=p.id;result_response:=jsonb_build_object('policyId',p.id,'artifactType',kind,'policyVersion',p.policy_version,'retentionDays',p.retention_days,'indefinite',p.indefinite,'effectiveAt',p.effective_at);
 ELSE
  IF command_type='studio.legal_hold.release' THEN BEGIN result_resource_id:=(p_command#>>'{payload,holdId}')::uuid;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;SELECT placed.* INTO hold FROM public.studio_rendition_legal_hold_events placed WHERE placed.hold_id=result_resource_id AND placed.event_type='placed' AND placed.org_id=org AND placed.workspace_id=workspace;IF hold.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;SELECT * INTO r FROM public.studio_renditions WHERE id=hold.rendition_id AND org_id=org AND workspace_id=workspace FOR UPDATE;
  ELSIF command_type='studio.rendition.deletion.resolve' THEN BEGIN result_resource_id:=(p_command#>>'{payload,deletionRequestId}')::uuid;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;SELECT * INTO dr FROM public.studio_rendition_deletion_requests WHERE id=result_resource_id AND org_id=org AND workspace_id=workspace;IF dr.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;SELECT * INTO r FROM public.studio_renditions WHERE id=dr.rendition_id AND org_id=org AND workspace_id=workspace FOR UPDATE;
  ELSE BEGIN result_resource_id:=(p_command#>>'{payload,renditionId}')::uuid;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;SELECT * INTO r FROM public.studio_renditions WHERE id=result_resource_id AND org_id=org AND workspace_id=workspace FOR UPDATE;END IF;
  IF r.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(r.id::text,0));IF length(btrim(COALESCE(p_command#>>'{payload,rationale}',''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;
  IF command_type='studio.rendition.retention.extend' THEN retention:=public.studio_effective_retention(r.id);BEGIN indef:=COALESCE((p_command#>>'{payload,indefinite}')::boolean,false);until_at:=NULLIF(p_command#>>'{payload,extendUntil}','')::timestamptz;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;IF retention->>'indefinite'='true' OR (NOT indef AND(until_at IS NULL OR until_at<=COALESCE((retention->>'retentionUntil')::timestamptz,'-infinity'))) OR(indef AND until_at IS NOT NULL) THEN RAISE EXCEPTION USING MESSAGE='RETENTION_CANNOT_SHORTEN';END IF;INSERT INTO public.studio_rendition_retention_extensions(rendition_id,org_id,workspace_id,extended_until,indefinite,rationale,actor_id,actor_authorization_version,receipt_id,audit_event_id) VALUES(r.id,org,workspace,until_at,indef,p_command#>>'{payload,rationale}',actor,authorization_version,receipt.id,audit_id) RETURNING id INTO result_resource_id;result_response:=jsonb_build_object('renditionId',r.id,'retention',public.studio_effective_retention(r.id));
  ELSIF command_type='studio.legal_hold.place' THEN IF r.lifecycle='deleted' THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;event_id:=gen_random_uuid();INSERT INTO public.studio_rendition_legal_hold_events(id,hold_id,event_type,rendition_id,org_id,workspace_id,rationale,actor_id,actor_authorization_version,receipt_id,audit_event_id) VALUES(event_id,event_id,'placed',r.id,org,workspace,p_command#>>'{payload,rationale}',actor,authorization_version,receipt.id,audit_id);result_resource_id:=event_id;result_response:=jsonb_build_object('holdId',event_id,'renditionId',r.id,'active',true);
  ELSIF command_type='studio.legal_hold.release' THEN IF EXISTS(SELECT 1 FROM public.studio_rendition_legal_hold_events WHERE hold_id=hold.hold_id AND event_type='released') THEN RAISE EXCEPTION USING MESSAGE='VERSION_CONFLICT';END IF;event_id:=gen_random_uuid();INSERT INTO public.studio_rendition_legal_hold_events(id,hold_id,event_type,place_event_id,rendition_id,org_id,workspace_id,rationale,actor_id,actor_authorization_version,receipt_id,audit_event_id) VALUES(event_id,hold.hold_id,'released',hold.id,r.id,org,workspace,p_command#>>'{payload,rationale}',actor,authorization_version,receipt.id,audit_id);result_resource_id:=hold.hold_id;result_response:=jsonb_build_object('holdId',hold.hold_id,'renditionId',r.id,'active',false);
  ELSIF command_type='studio.rendition.deletion.request' THEN IF r.lifecycle NOT IN('available','deletion_failed') THEN RAISE EXCEPTION USING MESSAGE='VERSION_CONFLICT';END IF;retention:=public.studio_effective_retention(r.id);holds:=public.studio_active_hold_count(r.id);INSERT INTO public.studio_rendition_deletion_requests(rendition_id,org_id,workspace_id,requested_by,requester_authorization_version,rationale,requested_lifecycle,requested_lifecycle_version,retention_evaluation,active_hold_count,receipt_id,audit_event_id) VALUES(r.id,org,workspace,actor,authorization_version,p_command#>>'{payload,rationale}',r.lifecycle,r.lifecycle_version,retention,holds,receipt.id,audit_id) RETURNING * INTO dr;UPDATE public.studio_renditions SET lifecycle='deletion_requested',lifecycle_version=lifecycle_version+1,updated_at=now() WHERE id=r.id;result_resource_id:=dr.id;result_response:=jsonb_build_object('deletionRequestId',dr.id,'renditionId',r.id,'status','pending');
  ELSE IF dr.requested_by=actor THEN RAISE EXCEPTION USING MESSAGE='STUDIO_SEPARATION_OF_DUTY';END IF;outcome:=p_command#>>'{payload,outcome}';IF outcome NOT IN('approve','reject') OR r.lifecycle<>'deletion_requested' THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;retention:=public.studio_effective_retention(r.id);holds:=public.studio_active_hold_count(r.id);IF outcome='approve' AND(retention->>'indefinite'='true' OR COALESCE((retention->>'retentionUntil')::timestamptz,'infinity')>now() OR holds>0) THEN RAISE EXCEPTION USING MESSAGE='STUDIO_DELETION_BLOCKED';END IF;INSERT INTO public.studio_rendition_deletion_resolutions(request_id,rendition_id,org_id,workspace_id,resolved_by,resolver_authorization_version,outcome,rationale,retention_evaluation,active_hold_count,receipt_id,audit_event_id) VALUES(dr.id,r.id,org,workspace,actor,authorization_version,CASE outcome WHEN 'approve' THEN 'approved' ELSE 'rejected' END,p_command#>>'{payload,rationale}',retention,holds,receipt.id,audit_id) RETURNING * INTO ds;IF outcome='approve' THEN IF NOT control.deletion_enabled OR NOT control.provider_enabled THEN RAISE EXCEPTION USING MESSAGE='STUDIO_READ_ONLY';END IF;INSERT INTO public.studio_rendition_deletion_attempts(resolution_id,request_id,rendition_id,org_id,workspace_id,state) VALUES(ds.id,dr.id,r.id,org,workspace,'requested') RETURNING * INTO da;UPDATE public.studio_renditions SET lifecycle='deleting',lifecycle_version=lifecycle_version+1,updated_at=now() WHERE id=r.id;claim:=jsonb_build_object('disposition','execute','requestId',request_id,'deletionAttemptId',da.id,'renditionId',r.id,'organizationId',org,'workspaceId',workspace,'objectKey',r.object_key,'reconciliationCount',da.reconciliation_count);result_response:=jsonb_build_object('deletionRequestId',dr.id,'resolutionId',ds.id,'renditionId',r.id,'status','deleting');ELSE UPDATE public.studio_renditions SET lifecycle='available',lifecycle_version=lifecycle_version+1,updated_at=now() WHERE id=r.id;result_response:=jsonb_build_object('deletionRequestId',dr.id,'resolutionId',ds.id,'renditionId',r.id,'status','rejected');END IF;result_resource_id:=ds.id;END IF;
 END IF;
 INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,org,workspace,actor,request_id,command_type,CASE WHEN command_type='studio.rendition.generate' THEN 'studio_rendition_attempt' WHEN command_type='studio.retention.policy.publish' THEN 'studio_retention_policy' WHEN command_type LIKE 'studio.legal_hold.%' THEN 'studio_legal_hold' WHEN command_type='studio.rendition.deletion.request' THEN 'studio_deletion_request' WHEN command_type='studio.rendition.deletion.resolve' THEN 'studio_deletion_resolution' ELSE 'studio_retention_extension' END,result_resource_id,'succeeded',COALESCE(r.lifecycle_version,1),jsonb_build_object('receiptId',receipt.id));
 UPDATE public.studio_private_artifact_command_receipts SET resource_id=result_resource_id,response=result_response WHERE id=receipt.id;
 RETURN jsonb_build_object('outcome','committed','receiptId',receipt.id,'resourceId',result_resource_id,'resource',result_response)||CASE WHEN command_type='studio.rendition.generate' THEN jsonb_build_object('renditionClaim',claim) WHEN command_type='studio.rendition.deletion.resolve' AND claim IS NOT NULL THEN jsonb_build_object('deletionClaim',claim) ELSE '{}'::jsonb END;
END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_attempt_start(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x public.studio_rendition_attempts;audit_id uuid:=gen_random_uuid();BEGIN SELECT * INTO x FROM public.studio_rendition_attempts WHERE id=p_attempt FOR UPDATE;IF x.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM public.studio_assert_actor(x.requested_by,x.org_id,x.workspace_id,'studio.artifacts.rendition.generate',x.requester_authorization_version);IF x.state='rendering' THEN RETURN jsonb_build_object('outcome','replayed','attemptId',x.id,'state',x.state);END IF;IF x.state<>'requested' THEN RAISE EXCEPTION USING MESSAGE='VERSION_CONFLICT';END IF;UPDATE public.studio_rendition_attempts SET state='rendering',started_at=now() WHERE id=x.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,x.org_id,x.workspace_id,x.requested_by,x.request_id,'studio.rendition.attempt.start','studio_rendition_attempt',x.id,'succeeded',2,jsonb_build_object('attemptId',x.id,'format',x.format));RETURN jsonb_build_object('outcome','committed','attemptId',x.id,'state','rendering');END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_attempt_rendered(p_attempt uuid,p_object_key text,p_hash text,p_byte_length bigint,p_mime text,p_safe_filename text,p_renderer_version text,p_template_version text,p_content_schema_version text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x public.studio_rendition_attempts;expected_key text;expected_mime text;extension text;audit_id uuid:=gen_random_uuid();BEGIN SELECT * INTO x FROM public.studio_rendition_attempts WHERE id=p_attempt FOR UPDATE;IF x.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM public.studio_assert_actor(x.requested_by,x.org_id,x.workspace_id,'studio.artifacts.rendition.generate',x.requester_authorization_version);extension:=CASE x.format WHEN 'markdown' THEN 'md' ELSE x.format END;expected_mime:=CASE x.format WHEN 'markdown' THEN 'text/markdown; charset=utf-8' WHEN 'pdf' THEN 'application/pdf' ELSE 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' END;expected_key:=format('%s/%s/studio-artifacts/%s.%s',x.org_id,x.workspace_id,x.opaque_object_id,extension);IF x.state='uploaded' THEN IF x.object_key IS DISTINCT FROM p_object_key OR x.content_hash IS DISTINCT FROM p_hash OR x.byte_length IS DISTINCT FROM p_byte_length OR x.mime_type IS DISTINCT FROM p_mime OR x.safe_filename IS DISTINCT FROM p_safe_filename OR x.renderer_version IS DISTINCT FROM p_renderer_version OR x.template_version IS DISTINCT FROM p_template_version OR x.content_schema_version IS DISTINCT FROM p_content_schema_version THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;RETURN jsonb_build_object('outcome','replayed','attemptId',x.id,'state',x.state);END IF;IF x.state<>'rendering' OR p_object_key IS DISTINCT FROM expected_key OR p_hash!~'^[0-9a-f]{64}$' OR p_byte_length<=0 OR p_mime IS DISTINCT FROM expected_mime OR p_renderer_version IS DISTINCT FROM x.renderer_version OR p_template_version IS DISTINCT FROM x.template_version OR p_content_schema_version IS DISTINCT FROM x.content_schema_version OR p_safe_filename!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$' OR lower(right(p_safe_filename,length(extension)+1))<>'.'||extension THEN RAISE EXCEPTION USING MESSAGE='INVALID_RENDITION_METADATA';END IF;UPDATE public.studio_rendition_attempts SET state='uploaded',storage_provider='supabase',bucket_id='studio-private-artifacts',object_key=p_object_key,content_hash=p_hash,byte_length=p_byte_length,mime_type=p_mime,safe_filename=p_safe_filename,rendered_at=now() WHERE id=x.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,x.org_id,x.workspace_id,x.requested_by,x.request_id,'studio.rendition.attempt.rendered','studio_rendition_attempt',x.id,'succeeded',3,jsonb_build_object('attemptId',x.id,'format',x.format,'contentHash',p_hash,'byteLength',p_byte_length,'mimeType',p_mime,'rendererVersion',p_renderer_version,'templateVersion',p_template_version,'contentSchemaVersion',p_content_schema_version));RETURN jsonb_build_object('outcome','committed','attemptId',x.id,'state','uploaded');END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_attempt_complete(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x public.studio_rendition_attempts;r public.studio_renditions;p public.studio_retention_policies;audit_id uuid:=gen_random_uuid();BEGIN SELECT * INTO x FROM public.studio_rendition_attempts WHERE id=p_attempt FOR UPDATE;IF x.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM public.studio_assert_actor(x.requested_by,x.org_id,x.workspace_id,'studio.artifacts.rendition.generate',x.requester_authorization_version);SELECT * INTO r FROM public.studio_renditions WHERE attempt_id=x.id;IF x.state='available' AND r.id IS NOT NULL THEN RETURN jsonb_build_object('outcome','replayed','renditionId',r.id,'state','available');END IF;IF x.state NOT IN('uploaded','reconciling') THEN RAISE EXCEPTION USING MESSAGE='VERSION_CONFLICT';END IF;SELECT * INTO p FROM public.studio_retention_policies WHERE(system_default OR(org_id=x.org_id AND workspace_id=x.workspace_id AND artifact_type=x.artifact_type)) AND effective_at<=now() ORDER BY system_default ASC,effective_at DESC,policy_version DESC LIMIT 1 FOR SHARE;IF p.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RETENTION_POLICY_UNAVAILABLE';END IF;INSERT INTO public.studio_renditions(id,attempt_id,org_id,workspace_id,artifact_id,artifact_version_id,artifact_version,artifact_type,format,mime_type,safe_filename,storage_provider,bucket_id,object_key,byte_length,content_hash,renderer_version,template_version,content_schema_version,retention_policy_id,retention_policy_version,retention_indefinite,retention_until,lifecycle) VALUES(x.rendition_id,x.id,x.org_id,x.workspace_id,x.artifact_id,x.artifact_version_id,x.artifact_version,x.artifact_type,x.format,x.mime_type,x.safe_filename,x.storage_provider,x.bucket_id,x.object_key,x.byte_length,x.content_hash,x.renderer_version,x.template_version,x.content_schema_version,p.id,p.policy_version,p.indefinite,CASE WHEN p.indefinite THEN NULL ELSE now()+make_interval(days=>p.retention_days) END,'available') RETURNING * INTO r;UPDATE public.studio_rendition_attempts SET state='available',failure_code=NULL,reconciliation_claimed_at=NULL,completed_at=now() WHERE id=x.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,x.org_id,x.workspace_id,x.requested_by,x.request_id,'studio.rendition.attempt.complete','studio_rendition',r.id,'succeeded',1,jsonb_build_object('attemptId',x.id,'artifactVersionId',x.artifact_version_id,'format',x.format,'contentHash',x.content_hash,'byteLength',x.byte_length,'retentionPolicyId',p.id,'retentionPolicyVersion',p.policy_version));RETURN jsonb_build_object('outcome','committed','renditionId',r.id,'state','available');END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_attempt_fail(p_attempt uuid,p_failure text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE x public.studio_rendition_attempts;audit_id uuid:=gen_random_uuid();target_state text;next_count integer;BEGIN SELECT * INTO x FROM public.studio_rendition_attempts WHERE id=p_attempt FOR UPDATE;IF x.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM public.studio_assert_actor(x.requested_by,x.org_id,x.workspace_id,'studio.artifacts.rendition.generate',x.requester_authorization_version);IF p_failure!~'^[A-Z0-9_]{1,64}$' THEN RAISE EXCEPTION USING MESSAGE='INVALID_FAILURE';END IF;target_state:=CASE WHEN p_failure IN('UPLOAD_OUTCOME_UNKNOWN','AVAILABLE_COMPLETION_FAILED') THEN 'reconciliation_required' ELSE 'failed' END;next_count:=CASE WHEN target_state='reconciliation_required' THEN x.reconciliation_count+1 ELSE x.reconciliation_count END;IF x.state=target_state THEN IF x.failure_code IS DISTINCT FROM p_failure THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;RETURN jsonb_build_object('outcome','replayed','attemptId',x.id,'state',x.state);END IF;IF x.state NOT IN('requested','rendering','uploaded','reconciliation_required','reconciling') OR next_count>3 THEN RAISE EXCEPTION USING MESSAGE='INVALID_FAILURE';END IF;UPDATE public.studio_rendition_attempts SET state=target_state,failure_code=p_failure,reconciliation_count=next_count,reconciliation_claimed_at=NULL,completed_at=CASE WHEN target_state='failed' THEN now() ELSE NULL END WHERE id=x.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,x.org_id,x.workspace_id,x.requested_by,x.request_id,'studio.rendition.attempt.fail','studio_rendition_attempt',x.id,CASE WHEN target_state='failed' THEN 'failed' ELSE 'pending' END,4,jsonb_build_object('attemptId',x.id,'failureCode',p_failure,'state',target_state,'reconciliationCount',next_count));RETURN jsonb_build_object('outcome','committed','attemptId',x.id,'state',target_state);END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_deletion_complete(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a public.studio_rendition_deletion_attempts;d public.studio_rendition_deletion_resolutions;r public.studio_renditions;retention jsonb;holds integer;audit_id uuid:=gen_random_uuid();BEGIN SELECT * INTO a FROM public.studio_rendition_deletion_attempts WHERE id=p_attempt FOR UPDATE;IF a.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;SELECT * INTO d FROM public.studio_rendition_deletion_resolutions WHERE id=a.resolution_id;PERFORM public.studio_assert_actor(d.resolved_by,d.org_id,d.workspace_id,'studio.artifacts.delete.approve',d.resolver_authorization_version);SELECT * INTO r FROM public.studio_renditions WHERE id=a.rendition_id FOR UPDATE;IF a.state='completed' AND r.lifecycle='deleted' THEN RETURN jsonb_build_object('outcome','replayed','attemptId',a.id,'state','deleted');END IF;retention:=public.studio_effective_retention(r.id);holds:=public.studio_active_hold_count(r.id);IF a.state NOT IN('requested','reconciliation_required','reconciling') OR r.lifecycle<>'deleting' OR holds>0 OR retention->>'indefinite'='true' OR COALESCE((retention->>'retentionUntil')::timestamptz,'infinity')>now() THEN RAISE EXCEPTION USING MESSAGE='STUDIO_DELETION_BLOCKED';END IF;UPDATE public.studio_rendition_deletion_attempts SET state='completed',failure_code=NULL,reconciliation_claimed_at=NULL,completed_at=now() WHERE id=a.id;UPDATE public.studio_renditions SET lifecycle='deleted',lifecycle_version=lifecycle_version+1,updated_at=now(),deleted_at=now() WHERE id=r.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) SELECT audit_id,r.org_id,r.workspace_id,d.resolved_by,cr.request_id,'studio.rendition.deletion.complete','studio_rendition',r.id,'succeeded',r.lifecycle_version+1,jsonb_build_object('attemptId',a.id,'contentHash',r.content_hash,'byteLength',r.byte_length,'format',r.format) FROM public.studio_private_artifact_command_receipts cr WHERE cr.id=d.receipt_id;RETURN jsonb_build_object('outcome','committed','attemptId',a.id,'state','deleted');END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_deletion_fail(p_attempt uuid,p_failure text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a public.studio_rendition_deletion_attempts;d public.studio_rendition_deletion_resolutions;r public.studio_renditions;audit_id uuid:=gen_random_uuid();target_state text;next_count integer;BEGIN SELECT * INTO a FROM public.studio_rendition_deletion_attempts WHERE id=p_attempt FOR UPDATE;IF a.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;SELECT * INTO d FROM public.studio_rendition_deletion_resolutions WHERE id=a.resolution_id;PERFORM public.studio_assert_actor(d.resolved_by,d.org_id,d.workspace_id,'studio.artifacts.delete.approve',d.resolver_authorization_version);SELECT * INTO r FROM public.studio_renditions WHERE id=a.rendition_id FOR UPDATE;IF p_failure!~'^[A-Z0-9_]{1,64}$' THEN RAISE EXCEPTION USING MESSAGE='INVALID_FAILURE';END IF;target_state:=CASE WHEN p_failure IN('DELETE_OUTCOME_UNKNOWN','TOMBSTONE_COMPLETION_FAILED') THEN 'reconciliation_required' ELSE 'failed' END;next_count:=CASE WHEN target_state='reconciliation_required' THEN a.reconciliation_count+1 ELSE a.reconciliation_count END;IF a.state=target_state THEN IF a.failure_code IS DISTINCT FROM p_failure THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;RETURN jsonb_build_object('outcome','replayed','attemptId',a.id,'state',CASE WHEN target_state='failed' THEN 'deletion_failed' ELSE target_state END);END IF;IF a.state NOT IN('requested','reconciliation_required','reconciling') OR r.lifecycle<>'deleting' OR next_count>3 THEN RAISE EXCEPTION USING MESSAGE='INVALID_FAILURE';END IF;UPDATE public.studio_rendition_deletion_attempts SET state=target_state,failure_code=p_failure,reconciliation_count=next_count,reconciliation_claimed_at=NULL,completed_at=CASE WHEN target_state='failed' THEN now() ELSE NULL END WHERE id=a.id;IF target_state='failed' THEN UPDATE public.studio_renditions SET lifecycle='deletion_failed',lifecycle_version=lifecycle_version+1,updated_at=now() WHERE id=r.id;END IF;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) SELECT audit_id,r.org_id,r.workspace_id,d.resolved_by,cr.request_id,'studio.rendition.deletion.fail','studio_rendition',r.id,CASE WHEN target_state='failed' THEN 'failed' ELSE 'pending' END,r.lifecycle_version+CASE WHEN target_state='failed' THEN 1 ELSE 0 END,jsonb_build_object('attemptId',a.id,'failureCode',p_failure,'state',target_state,'reconciliationCount',next_count) FROM public.studio_private_artifact_command_receipts cr WHERE cr.id=d.receipt_id;RETURN jsonb_build_object('outcome','committed','attemptId',a.id,'state',CASE WHEN target_state='failed' THEN 'deletion_failed' ELSE target_state END);END$$;
CREATE OR REPLACE FUNCTION public.studio_rendition_reconciliation_claim(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE x public.studio_rendition_attempts;v public.studio_artifact_versions;control public.studio_private_artifact_runtime_control;audit_id uuid:=gen_random_uuid();next_count integer;extension text;expected_key text;
BEGIN
 SELECT * INTO x FROM public.studio_rendition_attempts WHERE id=p_attempt FOR UPDATE;
 IF x.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;
 PERFORM public.studio_assert_actor(x.requested_by,x.org_id,x.workspace_id,'studio.artifacts.rendition.generate',x.requester_authorization_version);
 SELECT * INTO control FROM public.studio_private_artifact_runtime_control WHERE singleton FOR SHARE;
 IF NOT control.enabled OR control.read_only OR NOT control.provider_enabled THEN RAISE EXCEPTION USING MESSAGE='STUDIO_READ_ONLY';END IF;
 SELECT sv.* INTO v FROM public.studio_artifact_versions sv JOIN public.studio_artifact_aggregates a ON a.id=sv.artifact_id AND a.org_id=sv.org_id AND a.workspace_id=sv.workspace_id WHERE sv.id=x.artifact_version_id AND sv.artifact_id=x.artifact_id AND sv.org_id=x.org_id AND sv.workspace_id=x.workspace_id AND a.current_approved_version_id=sv.id AND a.lifecycle='approved' AND sv.lifecycle='approved' FOR SHARE OF sv,a;
 IF v.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;
 IF x.state IN('available','failed') THEN RETURN NULL;END IF;
 IF x.state='reconciling' AND x.reconciliation_claimed_at>now()-interval '5 minutes' THEN RETURN NULL;END IF;
 IF x.state NOT IN('reconciliation_required','reconciling') THEN RETURN NULL;END IF;
 next_count:=x.reconciliation_count+CASE WHEN x.state='reconciling' THEN 1 ELSE 0 END;
 IF next_count>=3 THEN UPDATE public.studio_rendition_attempts SET state='failed',failure_code='RECONCILIATION_EXHAUSTED',reconciliation_count=3,reconciliation_claimed_at=NULL,completed_at=now() WHERE id=x.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,x.org_id,x.workspace_id,x.requested_by,x.request_id,'studio.rendition.reconciliation.exhausted','studio_rendition_attempt',x.id,'failed',5,jsonb_build_object('attemptId',x.id,'failureCode','RECONCILIATION_EXHAUSTED','reconciliationCount',3));RETURN NULL;END IF;
 extension:=CASE x.format WHEN 'markdown' THEN 'md' ELSE x.format END;expected_key:=format('%s/%s/studio-artifacts/%s.%s',x.org_id,x.workspace_id,x.opaque_object_id,extension);
 IF x.storage_provider IS DISTINCT FROM 'supabase' OR x.bucket_id IS DISTINCT FROM 'studio-private-artifacts' OR x.object_key IS DISTINCT FROM expected_key OR x.content_hash!~'^[0-9a-f]{64}$' OR x.byte_length<=0 OR x.mime_type IS DISTINCT FROM CASE x.format WHEN 'markdown' THEN 'text/markdown; charset=utf-8' WHEN 'pdf' THEN 'application/pdf' ELSE 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' END OR x.safe_filename!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$' THEN RAISE EXCEPTION USING MESSAGE='COMMAND_UNAVAILABLE';END IF;
 UPDATE public.studio_rendition_attempts SET state='reconciling',failure_code=NULL,reconciliation_count=next_count,reconciliation_claimed_at=now(),completed_at=NULL WHERE id=x.id;
 INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,x.org_id,x.workspace_id,x.requested_by,x.request_id,'studio.rendition.reconciliation.claim','studio_rendition_attempt',x.id,'pending',5,jsonb_build_object('attemptId',x.id,'format',x.format,'reconciliationCount',next_count));
 RETURN jsonb_build_object('attemptId',x.id,'renditionId',x.rendition_id,'organizationId',x.org_id,'workspaceId',x.workspace_id,'objectKey',x.object_key,'format',x.format,'artifactType',x.artifact_type,'artifactId',x.artifact_id,'artifactVersionId',x.artifact_version_id,'opaqueObjectId',x.opaque_object_id,'approvedContent',v.content,'contentSchemaVersion',x.content_schema_version,'byteLength',x.byte_length,'sha256',x.content_hash,'mimeType',x.mime_type,'filename',x.safe_filename,'rendererVersion',x.renderer_version,'templateVersion',x.template_version,'reconciliationCount',next_count);
END$$;
CREATE OR REPLACE FUNCTION public.studio_deletion_reconciliation_claim(p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a public.studio_rendition_deletion_attempts;d public.studio_rendition_deletion_resolutions;r public.studio_renditions;control public.studio_private_artifact_runtime_control;retention jsonb;holds integer;audit_id uuid:=gen_random_uuid();next_count integer;
BEGIN
 SELECT * INTO a FROM public.studio_rendition_deletion_attempts WHERE id=p_attempt FOR UPDATE;
 IF a.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;
 SELECT * INTO d FROM public.studio_rendition_deletion_resolutions WHERE id=a.resolution_id AND outcome='approved';
 IF d.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;
 PERFORM public.studio_assert_actor(d.resolved_by,d.org_id,d.workspace_id,'studio.artifacts.delete.approve',d.resolver_authorization_version);
 SELECT * INTO control FROM public.studio_private_artifact_runtime_control WHERE singleton FOR SHARE;
 IF NOT control.enabled OR control.read_only OR NOT control.provider_enabled OR NOT control.deletion_enabled THEN RAISE EXCEPTION USING MESSAGE='STUDIO_READ_ONLY';END IF;
 SELECT * INTO r FROM public.studio_renditions WHERE id=a.rendition_id AND org_id=a.org_id AND workspace_id=a.workspace_id FOR UPDATE;
 IF r.id IS NULL OR r.bucket_id IS DISTINCT FROM 'studio-private-artifacts' OR r.storage_provider IS DISTINCT FROM 'supabase' OR r.object_key IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;
 IF a.state='completed' AND r.lifecycle='deleted' THEN RETURN NULL;END IF;
 retention:=public.studio_effective_retention(r.id);holds:=public.studio_active_hold_count(r.id);
 IF r.lifecycle<>'deleting' OR holds>0 OR retention->>'indefinite'='true' OR COALESCE((retention->>'retentionUntil')::timestamptz,'infinity')>now() THEN RAISE EXCEPTION USING MESSAGE='STUDIO_DELETION_BLOCKED';END IF;
 IF a.state='failed' THEN RETURN NULL;END IF;
 IF a.state='reconciling' AND a.reconciliation_claimed_at>now()-interval '5 minutes' THEN RETURN NULL;END IF;
 IF a.state NOT IN('reconciliation_required','reconciling') THEN RETURN NULL;END IF;
 next_count:=a.reconciliation_count+CASE WHEN a.state='reconciling' THEN 1 ELSE 0 END;
 IF next_count>=3 THEN UPDATE public.studio_rendition_deletion_attempts SET state='failed',failure_code='DELETION_RECONCILIATION_EXHAUSTED',reconciliation_count=3,reconciliation_claimed_at=NULL,completed_at=now() WHERE id=a.id;UPDATE public.studio_renditions SET lifecycle='deletion_failed',lifecycle_version=lifecycle_version+1,updated_at=now() WHERE id=r.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) SELECT audit_id,r.org_id,r.workspace_id,d.resolved_by,cr.request_id,'studio.rendition.deletion.reconciliation.exhausted','studio_rendition',r.id,'failed',r.lifecycle_version+1,jsonb_build_object('attemptId',a.id,'failureCode','DELETION_RECONCILIATION_EXHAUSTED','reconciliationCount',3) FROM public.studio_private_artifact_command_receipts cr WHERE cr.id=d.receipt_id;RETURN NULL;END IF;
 UPDATE public.studio_rendition_deletion_attempts SET state='reconciling',failure_code=NULL,reconciliation_count=next_count,reconciliation_claimed_at=now(),completed_at=NULL WHERE id=a.id;
 INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) SELECT audit_id,r.org_id,r.workspace_id,d.resolved_by,cr.request_id,'studio.rendition.deletion.reconciliation.claim','studio_rendition',r.id,'pending',r.lifecycle_version,jsonb_build_object('attemptId',a.id,'reconciliationCount',next_count) FROM public.studio_private_artifact_command_receipts cr WHERE cr.id=d.receipt_id;
 RETURN jsonb_build_object('deletionAttemptId',a.id,'renditionId',r.id,'organizationId',r.org_id,'workspaceId',r.workspace_id,'objectKey',r.object_key,'reconciliationCount',next_count);
END$$;
CREATE OR REPLACE FUNCTION public.studio_artifact_download_claim(p_command jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE actor uuid;org uuid;workspace uuid;rendition_id uuid;request_id uuid;authorization_version bigint;key text;hash text;r public.studio_renditions;d public.studio_artifact_download_receipts;control public.studio_private_artifact_runtime_control;audit_id uuid:=gen_random_uuid();private_claim jsonb;BEGIN IF p_command IS NULL OR jsonb_typeof(p_command)<>'object' OR NOT(p_command?&ARRAY['actorId','organizationId','workspaceId','renditionId','requestId','idempotencyKey','authorizationVersion']) THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END IF;BEGIN actor:=(p_command->>'actorId')::uuid;org:=(p_command->>'organizationId')::uuid;workspace:=(p_command->>'workspaceId')::uuid;rendition_id:=(p_command->>'renditionId')::uuid;request_id:=(p_command->>'requestId')::uuid;authorization_version:=(p_command->>'authorizationVersion')::bigint;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING MESSAGE='INVALID_COMMAND';END;key:=p_command->>'idempotencyKey';PERFORM public.studio_assert_actor(actor,org,workspace,'studio.artifacts.download',authorization_version);hash:=encode(public.digest(convert_to(p_command::text,'UTF8'),'sha256'),'hex');SELECT * INTO d FROM public.studio_artifact_download_receipts WHERE org_id=org AND actor_id=actor AND idempotency_key=key FOR UPDATE;IF d.id IS NOT NULL THEN IF d.workspace_id<>workspace OR d.rendition_id<>rendition_id OR d.request_hash<>hash THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;IF d.status='failed' THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;SELECT * INTO r FROM public.studio_renditions WHERE id=d.rendition_id AND org_id=d.org_id AND workspace_id=d.workspace_id;IF r.id IS NULL OR r.lifecycle<>'available' THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;private_claim:=jsonb_build_object('organizationId',r.org_id,'workspaceId',r.workspace_id,'renditionId',r.id,'objectKey',r.object_key,'byteLength',r.byte_length,'sha256',r.content_hash,'mimeType',r.mime_type,'filename',r.safe_filename);RETURN jsonb_build_object('outcome','replayed','receiptId',d.id,'resourceId',d.rendition_id,'resource',jsonb_build_object('renditionId',d.rendition_id,'status',d.status),'downloadClaim',private_claim);END IF;SELECT * INTO control FROM public.studio_private_artifact_runtime_control WHERE singleton FOR SHARE;IF NOT control.enabled OR control.read_only OR NOT control.provider_enabled OR NOT control.download_enabled THEN RAISE EXCEPTION USING MESSAGE='STUDIO_READ_ONLY';END IF;SELECT * INTO r FROM public.studio_renditions WHERE id=rendition_id AND org_id=org AND workspace_id=workspace FOR SHARE;IF r.id IS NULL OR r.lifecycle<>'available' THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;INSERT INTO public.studio_artifact_download_receipts(org_id,workspace_id,rendition_id,actor_id,actor_authorization_version,request_id,idempotency_key,request_hash,status) VALUES(org,workspace,r.id,actor,authorization_version,request_id,key,hash,'claimed') RETURNING * INTO d;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,org,workspace,actor,request_id,'studio.rendition.download.claim','studio_rendition',r.id,'succeeded',r.lifecycle_version,jsonb_build_object('downloadReceiptId',d.id,'format',r.format));private_claim:=jsonb_build_object('organizationId',r.org_id,'workspaceId',r.workspace_id,'renditionId',r.id,'objectKey',r.object_key,'byteLength',r.byte_length,'sha256',r.content_hash,'mimeType',r.mime_type,'filename',r.safe_filename);RETURN jsonb_build_object('outcome','committed','receiptId',d.id,'resourceId',r.id,'resource',jsonb_build_object('renditionId',r.id,'status','claimed'),'downloadClaim',private_claim);END$$;
CREATE OR REPLACE FUNCTION public.studio_artifact_download_complete(p_receipt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d public.studio_artifact_download_receipts;r public.studio_renditions;audit_id uuid:=gen_random_uuid();BEGIN SELECT * INTO d FROM public.studio_artifact_download_receipts WHERE id=p_receipt FOR UPDATE;IF d.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM public.studio_assert_actor(d.actor_id,d.org_id,d.workspace_id,'studio.artifacts.download',d.actor_authorization_version);IF d.status='completed' THEN RETURN jsonb_build_object('outcome','replayed','receiptId',d.id,'status',d.status);END IF;IF d.status<>'claimed' THEN RAISE EXCEPTION USING MESSAGE='VERSION_CONFLICT';END IF;SELECT * INTO r FROM public.studio_renditions WHERE id=d.rendition_id FOR SHARE;IF r.lifecycle<>'available' THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;UPDATE public.studio_artifact_download_receipts SET status='completed',completed_at=now() WHERE id=d.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,d.org_id,d.workspace_id,d.actor_id,d.request_id,'studio.rendition.download.complete','studio_rendition',r.id,'succeeded',r.lifecycle_version,jsonb_build_object('downloadReceiptId',d.id,'format',r.format));RETURN jsonb_build_object('outcome','committed','receiptId',d.id,'status','completed');END$$;
CREATE OR REPLACE FUNCTION public.studio_artifact_download_fail(p_receipt uuid,p_failure text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d public.studio_artifact_download_receipts;r public.studio_renditions;audit_id uuid:=gen_random_uuid();BEGIN SELECT * INTO d FROM public.studio_artifact_download_receipts WHERE id=p_receipt FOR UPDATE;IF d.id IS NULL THEN RAISE EXCEPTION USING MESSAGE='RESOURCE_NOT_AVAILABLE';END IF;PERFORM public.studio_assert_actor(d.actor_id,d.org_id,d.workspace_id,'studio.artifacts.download',d.actor_authorization_version);IF d.status='failed' THEN IF d.failure_code IS DISTINCT FROM p_failure THEN RAISE EXCEPTION USING MESSAGE='IDEMPOTENCY_CONFLICT';END IF;RETURN jsonb_build_object('outcome','replayed','receiptId',d.id,'status',d.status);END IF;IF d.status<>'claimed' OR p_failure!~'^[A-Z0-9_]{1,64}$' THEN RAISE EXCEPTION USING MESSAGE='INVALID_FAILURE';END IF;SELECT * INTO r FROM public.studio_renditions WHERE id=d.rendition_id;UPDATE public.studio_artifact_download_receipts SET status='failed',failure_code=p_failure,completed_at=now() WHERE id=d.id;INSERT INTO public.privileged_audit_events(id,org_id,workspace_id,actor_id,request_id,action,resource_type,resource_id,outcome,resource_version,metadata) VALUES(audit_id,d.org_id,d.workspace_id,d.actor_id,d.request_id,'studio.rendition.download.fail','studio_rendition',d.rendition_id,'failed',r.lifecycle_version,jsonb_build_object('downloadReceiptId',d.id,'failureCode',p_failure));RETURN jsonb_build_object('outcome','committed','receiptId',d.id,'status','failed');END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['studio_private_artifact_runtime_control','studio_retention_policies','studio_private_artifact_command_receipts','studio_rendition_attempts','studio_renditions','studio_rendition_retention_extensions','studio_rendition_legal_hold_events','studio_rendition_deletion_requests','studio_rendition_deletion_resolutions','studio_rendition_deletion_attempts','studio_artifact_download_receipts'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated',t);END LOOP;END$$;
-- Never create provider-owned Storage schemas/tables. Apply the bucket contract only when both provider tables exist.
DO $storage$ BEGIN IF to_regclass('storage.buckets') IS NOT NULL AND to_regclass('storage.objects') IS NOT NULL THEN INSERT INTO storage.buckets(id,name,public) VALUES('studio-private-artifacts','studio-private-artifacts',false) ON CONFLICT(id) DO UPDATE SET public=false;EXECUTE 'DROP POLICY IF EXISTS studio_private_artifacts_browser_deny ON storage.objects';EXECUTE $policy$CREATE POLICY studio_private_artifacts_browser_deny ON storage.objects AS RESTRICTIVE FOR ALL TO anon,authenticated USING(bucket_id <> 'studio-private-artifacts') WITH CHECK(bucket_id <> 'studio-private-artifacts')$policy$;END IF;END $storage$;
REVOKE ALL ON FUNCTION public.studio_private_reject_immutable(),public.studio_rendition_attempt_guard(),public.studio_rendition_guard(),public.studio_private_status_guard(),public.studio_private_receipt_guard(),public.studio_effective_retention(uuid),public.studio_active_hold_count(uuid),public.studio_private_projection_unchecked(uuid,uuid,uuid),public.studio_private_claim_receipt(text,uuid,uuid,uuid,uuid,text,text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.studio_private_artifact_projection(uuid,uuid,uuid),public.studio_private_artifact_authority(uuid,uuid,uuid),public.studio_private_artifact_command_claim(jsonb),public.studio_rendition_attempt_start(uuid),public.studio_rendition_attempt_rendered(uuid,text,text,bigint,text,text,text,text,text),public.studio_rendition_attempt_complete(uuid),public.studio_rendition_attempt_fail(uuid,text),public.studio_rendition_reconciliation_claim(uuid),public.studio_deletion_reconciliation_claim(uuid),public.studio_rendition_deletion_complete(uuid),public.studio_rendition_deletion_fail(uuid,text),public.studio_artifact_download_claim(jsonb),public.studio_artifact_download_complete(uuid),public.studio_artifact_download_fail(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.studio_private_artifact_projection(uuid,uuid,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.studio_private_artifact_authority(uuid,uuid,uuid),public.studio_private_artifact_command_claim(jsonb),public.studio_rendition_attempt_start(uuid),public.studio_rendition_attempt_rendered(uuid,text,text,bigint,text,text,text,text,text),public.studio_rendition_attempt_complete(uuid),public.studio_rendition_attempt_fail(uuid,text),public.studio_rendition_reconciliation_claim(uuid),public.studio_deletion_reconciliation_claim(uuid),public.studio_rendition_deletion_complete(uuid),public.studio_rendition_deletion_fail(uuid,text),public.studio_artifact_download_claim(jsonb),public.studio_artifact_download_complete(uuid),public.studio_artifact_download_fail(uuid,text) TO service_role;
COMMENT ON TABLE public.studio_renditions IS 'Canonical immutable metadata and tombstones for private renditions of exact current approved Studio artifact versions. Never hard delete.';
COMMENT ON TABLE public.studio_retention_policies IS 'Versioned retention authority. The safe system default is indefinite and is not a legal or compliance claim.';
